export function shuffle(items,rng=Math.random){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
export function createSession(ids,{mode='practice',random=true}={}){return {mode,queue:random?shuffle(ids):[...ids],total:ids.length,index:0,answers:[],current:null,options:[],history:[],startedAt:Date.now(),done:false}}
export function recordAnswer(session,q,choice){if(session.current!==null||session.done) return false;const correct=choice===q.correct;session.current={id:q.id,choice,correct};session.answers.push({...session.current,repeat:session.history.some(a=>a.id===q.id)});session.history.push({...session.current});if(session.mode==='practice'&&!correct){/* Two intervening questions, or sooner when fewer remain. */session.queue.splice(Math.min(session.index+3,session.queue.length),0,q.id)}return true}
export function advance(session){if(session.current===null)return false;session.index++;session.current=null;session.options=[];session.done=session.index>=session.queue.length;return true}
export function firstAttemptScore(answers){const seen=new Set;const first=answers.filter(a=>{if(seen.has(a.id))return false;seen.add(a.id);return true});return {correct:first.filter(a=>a.correct).length,total:first.length}}
export function updateProgress(progress,id,correct){const prev=progress[id]||{attempts:0,correct:0,wrong:0,streak:0,mastered:false};const next={...prev,attempts:prev.attempts+1,correct:prev.correct+(correct?1:0),wrong:prev.wrong+(correct?0:1),streak:correct?prev.streak+1:0,lastCorrect:correct};next.mastered=correct;return {...progress,[id]:next}}
